import{_ as e,o as r,c as a,a6 as o}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"Jev 原理与应用","description":"用大白话拆解 TypeSafe AI 在 2026 年 9 月发布的 Jev——一个不写字、只给“带概率的决策”的 System One 模型：它是什么、为什么快、校准是什么意思、怎么调用、能用在哪、哪些话还只是官方口径。","frontmatter":{"title":"Jev 原理与应用","description":"用大白话拆解 TypeSafe AI 在 2026 年 9 月发布的 Jev——一个不写字、只给“带概率的决策”的 System One 模型：它是什么、为什么快、校准是什么意思、怎么调用、能用在哪、哪些话还只是官方口径。","source":"https://daiw.org/manual/jev"},"headers":[],"relativePath":"manual/llm/jev/index.md","filePath":"manual/llm/jev/index.md"}'),n={name:"manual/llm/jev/index.md"};function l(s,t,d,i,p,g){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="jev-原理与应用" tabindex="-1">Jev 原理与应用 <a class="header-anchor" href="#jev-原理与应用" aria-label="Permalink to &quot;Jev 原理与应用&quot;">​</a></h1><blockquote><p>内容来源：<a href="https://daiw.org/manual/jev" target="_blank" rel="noreferrer">daiw.org</a> · 作者 David（道雾轩） · 原文更新于 2026-11-06</p></blockquote><blockquote><p>用大白话拆解 TypeSafe AI 在 2026 年 9 月发布的 Jev——一个不写字、只给“带概率的决策”的 System One 模型：它是什么、为什么快、校准是什么意思、怎么调用、能用在哪、哪些话还只是官方口径。</p></blockquote><h2 id="序-·-一个不说话的模型" tabindex="-1">序 · 一个不说话的模型 <a class="header-anchor" href="#序-·-一个不说话的模型" aria-label="Permalink to &quot;序 · 一个不说话的模型&quot;">​</a></h2><p>大模型这几年给人的印象是“会说话”：你问一句，它一个字一个字地写出一段回答。但软件里的很多问题其实用不着一段话——这封邮件是不是投诉？这个工单该派给哪个组？这一步操作 Agent 能不能执行？它们要的只是<strong>一个选择，外加一个“有多大把握”</strong>。</p><p>2026 年 9 月 15 日，旧金山的创业公司 TypeSafe AI 发布了 Jev，押的正是这件事。它不生成文本，而是按调用方事先定义好的类型，一次性给出每个选项的概率；公司把这类模型叫作 <strong>System One 模型</strong>，借用心理学里“快思考”的说法，与擅长慢慢推理的大语言模型分工。名字取自 19 世纪英国经济学家 William Stanley Jevons——“杰文斯悖论”的那位 Jevons。</p><p>这个专栏用大白话，从“它到底是什么”讲到“背后的两条原理”，再讲到“怎么用、用在哪、还有哪些没被证实”。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>资料说明</strong>：Jev 发布于 2026 年 9 月中旬，并于 <strong>2026 年 10 月 14 日</strong>迭代至 <code>Jev 1.14</code>（<code>jev-1.14.0</code>，新增图像输入、第四种原语 <code>Box</code> 边界框定位与 262k 长上下文模式），目前<strong>没有论文，也没有公开的技术报告</strong>。本专栏以 TypeSafe 官网、官方博客《Introducing System One Models &amp; Jev》与官方文档为主要依据，初稿成文于 <strong>2026 年 9 月 19 日</strong>，并于 <strong>2026 年 11 月初</strong>复核更新。凡是厂商自述、没有第三方复现的数字，正文一律标“官方口径”；媒体报道与个人测试标明出处；官方没公开的（例如参数量、具体网络结构、训练数据细节），就写“尚未公开”，不做推测。</p></div><h2 id="先看结论" tabindex="-1">先看结论 <a class="header-anchor" href="#先看结论" aria-label="Permalink to &quot;先看结论&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>一句话回答</th></tr></thead><tbody><tr><td>它输出什么</td><td>不是文本，而是调用方预先定义好的类型里的选项（选择、打分、是非或图像边界框），外加每个选项的概率与置信度</td></tr><tr><td>为什么快</td><td>不逐个 token 往外写，而是一次并行给出全部答案；官方称比前沿 LLM 快 40–200 倍（官方口径，有前提）</td></tr><tr><td>“不会幻觉”是什么意思</td><td>输出只能落在预先定义的选项或坐标范围里，不会编出选项之外的东西；但选错仍然可能</td></tr><tr><td>校准是什么</td><td>它说有 85% 把握时，这类判断应当真有约 85% 是对的；训练方法叫 RLCD</td></tr><tr><td>怎么收费</td><td>按输入 token 计费（$42 / 十亿 token，即 $0.042 / 百万 token）、输出免费（官方定价，以官网为准）</td></tr><tr><td>现在能不能信</td><td>更快更省在第一批独立测试里得到了印证，但幅度比官方数字小；准确率与校准还缺大规模独立评测</td></tr></tbody></table><h2 id="这个专栏怎么走" tabindex="-1">这个专栏怎么走 <a class="header-anchor" href="#这个专栏怎么走" aria-label="Permalink to &quot;这个专栏怎么走&quot;">​</a></h2><p><strong>第 0 部分 · 先看全貌</strong></p><ul><li><strong>Jev 是什么</strong> —— 公司与团队、发布与迭代时间线、名字的由来，以及它想解决的问题。</li><li><strong>System One：快思考模型</strong> —— 从卡尼曼的系统 1 / 系统 2 讲起：它和 LLM 怎么分工，和 JSON 模式、分类器、嵌入模型有何不同。</li></ul><p><strong>第 1 部分 · 原理</strong></p><ul><li><strong>一次给出全部答案的并行采样</strong> —— 为什么 LLM 只能逐字写、并行生成有哪些公开路线，TypeSafe 说了什么、没说什么。</li><li><strong>RLCD 与概率校准</strong> —— 可靠性图、ECE、Brier 分数与恰当评分规则怎么读，RLCD 和 RLHF 有何不同。</li></ul><p><strong>第 2 部分 · 应用</strong></p><ul><li><strong>上手：类型、调用与计价</strong> —— 照着官方文档走一遍四种题型、图像与长上下文输入、SDK、计价与延迟。</li><li><strong>应用：从分类路由到玩 Doom</strong> —— 官方与早期用户公开的用例，以及两个实时演示。</li><li><strong>局限与展望</strong> —— 官方评测怎么读、第一批独立测试说明了什么、它做不好什么，以及杰文斯悖论之问。</li></ul><p>最后一篇<strong>回顾</strong>把全书串起来。</p><h2 id="和站内其他专栏的关系" tabindex="-1">和站内其他专栏的关系 <a class="header-anchor" href="#和站内其他专栏的关系" aria-label="Permalink to &quot;和站内其他专栏的关系&quot;">​</a></h2><p>如果你想先弄懂“大语言模型为什么只能一个 token 一个 token 地写”，可以先读<a href="https://daiw.org/manual/llm-anatomy" target="_blank" rel="noreferrer">《AI 大模型解构》</a>；想看同期另一条前沿方向——让 AI 参与改进 AI 自己——见<a href="https://daiw.org/manual/rsi" target="_blank" rel="noreferrer">《RSI 技术探究》</a>。</p><p>准备好了，就从 <a href="/Front2Full/manual/llm/jev/what-is-jev">Jev 是什么</a> 开始。</p>',21)])])}const m=e(n,[["render",l]]);export{h as __pageData,m as default};
